cd /work; python3 - <<'EOF'
H = open('deploy.log').readlines()[0].rstrip('\n')
lines = [l.rstrip('\n') for l in open('deploy.log') if l.startswith('ERROR')]
strs = [H]+lines
def overlap(a,b):
    m=0
    for k in range(1,min(len(a),len(b))+1):
        if a[-k:]==b[:k]:
            m=k
    return m
for i,a in enumerate(strs):
    for j,b in enumerate(strs):
        if i!=j:
            print(i,j,overlap(a,b))
